<script setup>
import {reactive,ref,onMounted} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {state,login,register,logout,notify,authRequest,homeFor,rememberedEmail,demoAccounts} from '../lib/state'
const router=useRouter(),route=useRoute(),signup=ref(false),busy=ref(false)
const form=reactive({name:'',email:rememberedEmail(),password:'',role:'client'})
const remember=ref(!!rememberedEmail())
const editing=ref(false)
const pref=reactive({name:'',budget:100,district:'Miraflores',interests:[],day:''})
function fill(){if(!state.user)return;Object.assign(pref,{name:state.user.name,budget:state.user.preferences?.budget??100,district:state.user.preferences?.district||'Miraflores',interests:[...(state.user.preferences?.interests||[])],day:state.user.preferences?.day||''})}
onMounted(fill)
async function submit(){try{busy.value=true;const user=signup.value?await register(form,remember.value):await login(form.email,form.password,remember.value);form.password='';notify(`Bienvenido/a, ${user.name}`);fill();const next=String(route.query.redirect||'');router.push(next.startsWith('/')&&!next.startsWith('//')?next:homeFor(user))}catch(e){notify(e.message)}finally{busy.value=false}}
function useDemo(role){signup.value=false;form.email=demoAccounts[role];form.password=demoAccounts.password}
async function save(){try{busy.value=true;const {user}=await authRequest('/me',{method:'PATCH',body:{name:pref.name,preferences:{budget:Number(pref.budget),district:pref.district,interests:pref.interests,day:pref.day}}});state.user=user;editing.value=false;notify('Preferencias guardadas.')}catch(e){notify(e.message)}finally{busy.value=false}}
async function out(){try{await logout();form.email=rememberedEmail();notify('Sesión cerrada.')}catch(e){notify(e.message)}}
</script>
<template><div class="page account-page"><div class="page-heading"><div><div class="eyebrow earth">ACCESO A HOBBIZ</div><h1>Mi cuenta</h1><p class="muted">Accede como cliente o tallerista y administra tus preferencias.</p></div></div>
<section v-if="state.user" class="form-card account-card"><div class="profile-banner"><span class="avatar big">{{state.user.name.slice(0,1)}}</span><div><h2>{{state.user.name}}</h2><p>{{state.user.email}} · {{state.user.role==='client'?'Cliente':'Tallerista'}}</p><small>{{state.mode==='demo'?'Cuenta de demostración (temporal)':'Cuenta con Firebase y MongoDB'}}</small></div></div><button class="btn outline" @click="editing=!editing">{{editing?'Cancelar':'Editar preferencias'}}</button> <button class="btn ghost" @click="out">Cerrar sesión</button>
<form v-if="editing" class="form-grid account-form" @submit.prevent="save"><label>Nombre<input v-model="pref.name" required minlength="2" maxlength="100"/></label><label>Presupuesto S/<input v-model.number="pref.budget" type="number" min="0" max="9999" required/></label><label>Distrito<select v-model="pref.district"><option v-for="d in state.meta.districts" :key="d">{{d}}</option></select></label><label>Día preferido<select v-model="pref.day"><option value="">Cualquier día</option><option v-for="d in ['lunes','martes','miércoles','jueves','viernes','sábado','domingo']" :key="d">{{d}}</option></select></label><div class="span-all"><h3>Intereses</h3><div class="interest-list"><label v-for="c in state.meta.categories" :key="c" class="interest"><input v-model="pref.interests" type="checkbox" :value="c"/> {{c}}</label></div></div><button class="btn primary" :disabled="busy">Guardar cambios</button></form></section>
<section v-else class="form-card account-card"><h2>{{signup?'Crear cuenta':'Iniciar sesión'}}</h2><p class="small muted">Para ver los talleres de Miraflores y Barranco necesitas iniciar sesión. {{state.mode==='demo'?'Modo demostración: los datos se reinician cuando se detiene el backend.':'Firebase Authentication autentica la sesión y MongoDB guarda el perfil.'}}</p><p v-if="route.query.redirect" class="card-note small">Inicia sesión para continuar a la página solicitada.</p><form class="account-form" @submit.prevent="submit"><label v-if="signup">Nombre completo<input v-model.trim="form.name" required minlength="2" maxlength="100"/></label><label>Correo electrónico<input v-model.trim="form.email" type="email" required/></label><label>Contraseña<input v-model="form.password" type="password" minlength="8" required autocomplete="current-password"/></label><label v-if="signup">Tipo de cuenta<select v-model="form.role"><option value="client">Cliente</option><option value="instructor">Tallerista</option></select></label><label class="remember"><input v-model="remember" type="checkbox"/> Recordarme en este dispositivo</label><p class="small muted remember-help">{{remember?'Tu sesión y tu correo se mantendrán hasta 30 días, aunque cierres el navegador.':'Tu sesión se cerrará al cerrar esta pestaña.'}}</p><button class="btn primary full" :disabled="busy">{{busy?'Validando...':signup?'Crear cuenta':'Ingresar'}}</button><button class="btn outline full" type="button" @click="signup=!signup">{{signup?'Ya tengo cuenta':'Crear una cuenta'}}</button></form>
<div v-if="state.mode==='demo' && !signup" class="demo-accounts"><p class="small muted">Cuentas de demostración (contraseña {{demoAccounts.password}}):</p><button class="btn light sm" type="button" @click="useDemo('client')">Usar cuenta cliente</button><button class="btn light sm" type="button" @click="useDemo('instructor')">Usar cuenta tallerista</button></div></section></div></template>
<style scoped>.account-card{max-width:680px;margin:28px auto;padding:28px}.account-form{display:grid;gap:17px;margin-top:20px}.account-form label{display:grid;gap:7px}.account-form input:not([type=checkbox]),.account-form select{width:100%;padding:13px;border:1px solid #dfcbb5;border-radius:12px}.account-form .interest-list{display:flex;gap:18px;flex-wrap:wrap}.account-form .interest{display:flex;gap:5px;align-items:center}.account-form .remember{display:flex;gap:8px;align-items:center;grid-template-columns:none}.remember-help{margin-top:-10px}.demo-accounts{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:18px;border-top:1px solid #eedfcf;padding-top:14px}.demo-accounts p{width:100%;margin:0}</style>
